def numIslands(grid):
    g = [list(row) for row in grid]; R = len(g); C = len(g[0]); cnt = 0
    for i in range(R):
        for j in range(C):
            if g[i][j] == "1":
                cnt += 1; st = [(i, j)]; g[i][j] = "0"
                while st:
                    x, y = st.pop()
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < R and 0 <= ny < C and g[nx][ny] == "1":
                            g[nx][ny] = "0"; st.append((nx, ny))
    return cnt
